      "content": "{\n  \"name\": \"@zilliz/memsearch-dsh\",\n  \"version\": \"0.1.7\",\n  \"description\": \"MemSearch plugin for DeepSeek Harness: shared markdown memory across agents, with capture, pre-step context injection, memory-recall skill, and a skill-candidate review panel.\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"exports\": {\n    \".\": {\n      \"types\": null,\n      \"default\": \"./index.js\"\n    },\n    \"./client\": \"./client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"runtime.js\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"prompts/\",\n    \"skills/\",\n    \"scripts/summarize.py\",\n    \"scripts/parse-transcript.py\",\n    \"scripts/derive-collection.sh\",\n    \"scripts/maintenance-runner.py\"\n  ],\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/zilliztech/memsearch\",\n    \"directory\": \"plugins/dsh\"\n  },\n  \"keywords\": [\n    \"memsearch\",\n    \"memory\",\n    \"deepseek-harness\",\n    \"cordis\",\n    \"plugin\"\n  ],\n  \"scripts\": {\n    \"test\": \"node --test tests/*.test.js\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"dependencies\": {\n    \"cross-spawn\": \"^7.0.6\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-llm\": \"*\"\n  }\n}\n"
